function downloadLocal(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
$('exportBackup').onclick=()=>{try{downloadLocal('shift-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(LocalShift.exportData(),null,2),'application/json');notify('Backup downloaded. Keep it somewhere safe.');}catch(e){notify(e.message);}};
$('importBackup').onclick=()=>$('backupFile').click();
$('backupFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>10000000)throw Error('Backup must be smaller than 10 MB.');const data=JSON.parse(await file.text());openModal('Restore this backup?','<p class="help">This replaces the employees, schedules and holiday dates saved in this browser. Your current administrator password stays unchanged. Export a backup of your current data first if you need to keep it.</p>',async()=>{LocalShift.restore(data);drafts={};notify('Backup restored in this browser.');},'Replace local data');}catch(err){notify('Could not import: '+err.message);}};
$('exportViewer').onclick=()=>{try{const conf=LocalShift.shared(),clone=document.documentElement.cloneNode(true);clone.querySelector('#local-config').textContent='window.LOCAL_CONFIG='+JSON.stringify(conf).replace(/</g,'\\u003c')+';';clone.querySelector('#modal').removeAttribute('open');clone.querySelector('#dialogBody').innerHTML='';clone.querySelector('#formError').textContent='';clone.querySelector('#notice').textContent='';clone.querySelectorAll('.admin-only').forEach(el=>el.hidden=true);clone.querySelector('#authButton').hidden=true;clone.querySelector('#localMode').textContent='Shared read-only snapshot · Changes are not synchronized';downloadLocal('shift-view-only.html','<!DOCTYPE html>\n'+clone.outerHTML,'text/html');notify('Read-only copy downloaded. Share the HTML file with your team.');}catch(e){notify(e.message);}};
const originalSignIn=$('authButton').onclick;
$('authButton').onclick=async()=>{if(!state?.readOnly&&!state?.admin&&!state?.passwordRequired){try{await api('login',{});await refresh();notify('Signed in as administrator. Password prompt is temporarily off.');}catch(e){notify(e.message);}return;}if(state?.adminConfigured||state?.admin)return originalSignIn();openModal('Create your local administrator','<p class="help">Username: <strong>admin</strong>. This password locks editing in this browser. It is a local convenience lock, not server security. Export regular backups: clearing browser data removes your schedules and password.</p><label class="field">New password<input name="password" type="password" required minlength="12" autocomplete="new-password"></label><label class="field">Confirm password<input name="confirm" type="password" required minlength="12" autocomplete="new-password"></label>',async form=>{if(form.get('password')!==form.get('confirm'))throw Error('The passwords do not match.');await api('setup',{password:form.get('password')});notify('Local administrator created. Your changes save in this browser.');},'Create administrator');};
const originalRender=render;
render=function(){originalRender();$('authButton').hidden=!!state.readOnly;$('localMode').textContent=state.readOnly?'Shared read-only snapshot · Changes are not synchronized':'Offline local edition · Saved in this browser · Export regular backups';$('enablePassword').hidden=!state.admin||state.readOnly||state.passwordRequired;if(state.passwordRequired&&!state.adminConfigured&&!state.readOnly)$('authButton').textContent='Set up administrator →';};
// The initial async refresh may have completed before these local controls loaded.
if(state)render();

$('enablePassword').onclick=()=>{if(state.adminConfigured){openModal('Enable password protection?','<p class="help">Your saved administrator password will be required at the next sign-in. Schedules and data stay unchanged.</p>',async()=>{await api('enablePassword',{});notify('Password protection enabled.');},'Enable password protection');return;}openModal('Enable password protection','<label class="field">New password<input name="password" type="password" required minlength="12" autocomplete="new-password"></label><label class="field">Confirm password<input name="confirm" type="password" required minlength="12" autocomplete="new-password"></label>',async form=>{if(form.get('password')!==form.get('confirm'))throw Error('The passwords do not match.');await api('setup',{password:form.get('password')});notify('Password protection enabled.');},'Enable password protection');};
